        let (gx, gy) = (x * sx, y * sy);
        let mut g = [0f32; 3];
        for (c, gc) in g.iter_mut().enumerate() {
            let src = if gain.channels == 3 { c } else { 0 };
            let norm = (gain.sample(gx, gy, src) / 255.0).clamp(0.0, 1.0).powf(inv_gamma[c]);
            *gc = m.min[c] + (m.max[c] - m.min[c]) * norm;
